-- Glenride System Map schema + seed.
-- Source: muse-backup-2026-11-08/glenride-system-map/data-snapshot-getmap.json (verbatim).
-- Tables are sysmap_*-prefixed; the shared glenride-hq D1 database also
-- hosts the Glenride HQ app's hq_* tables, which this migration never touches.

CREATE TABLE IF NOT EXISTS sysmap_departments (
  id INTEGER PRIMARY KEY, title TEXT NOT NULL, tagline TEXT NOT NULL DEFAULT '',
  mandate TEXT NOT NULL DEFAULT '', cost_center TEXT NOT NULL DEFAULT '',
  current_state TEXT NOT NULL DEFAULT '', future_state TEXT NOT NULL DEFAULT '',
  done_looks_like TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '',
  accent TEXT NOT NULL DEFAULT 'ember', is_core INTEGER NOT NULL DEFAULT 1,
  sort_order INTEGER NOT NULL DEFAULT 99, updated_at TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS sysmap_budget_stages (
  id INTEGER PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '',
  timing TEXT NOT NULL DEFAULT '', decision_rule TEXT NOT NULL DEFAULT '',
  sort_order INTEGER NOT NULL DEFAULT 99, updated_at TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS sysmap_hierarchy (
  id INTEGER PRIMARY KEY, title TEXT NOT NULL, holder TEXT NOT NULL DEFAULT '',
  responsibility TEXT NOT NULL DEFAULT '', sort_order INTEGER NOT NULL DEFAULT 99,
  updated_at TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS sysmap_organization (
  id INTEGER PRIMARY KEY CHECK (id = 1), premise TEXT NOT NULL DEFAULT '',
  current_title TEXT NOT NULL DEFAULT '', current_body TEXT NOT NULL DEFAULT '',
  future_title TEXT NOT NULL DEFAULT '', future_body TEXT NOT NULL DEFAULT '',
  updated_at TEXT NOT NULL DEFAULT '');

INSERT OR REPLACE INTO sysmap_departments (id,title,tagline,mandate,cost_center,current_state,future_state,done_looks_like,notes,accent,is_core,sort_order,updated_at) VALUES (1,'Research','Ask the hard questions. Publish the answers.','Supply-chain vulnerability research, pharmaceutical data evaluation, and enterprise systems analysis.','Researcher time, data feeds and subscriptions, compute for analysis, peer review, and editing.','Glenride’s supply-chain work, drug-shortage digest, and council charter.','A staffed research program that publishes durable findings and sets the institute’s agenda.','Published findings with receipts, cited and standing up to scrutiny.','','ember',1,1,'2026-10-08T17:36:47.000Z');
INSERT OR REPLACE INTO sysmap_departments (id,title,tagline,mandate,cost_center,current_state,future_state,done_looks_like,notes,accent,is_core,sort_order,updated_at) VALUES (2,'Applied AI Lab','Turn answers into software.','Build and maintain the systems that make Glenride’s research and ventures operational.','Engineering time, infrastructure, hardware upkeep, third-party security audits, APIs, and data.','Token systems, Vapor Wire bot, job scraper, and content-factory scaffold.','A disciplined product lab that turns institutional knowledge into software people can use or license.','Shipped software with users, documented and auditable.','','teal',1,2,'2026-10-08T17:36:47.000Z');
INSERT OR REPLACE INTO sysmap_departments (id,title,tagline,mandate,cost_center,current_state,future_state,done_looks_like,notes,accent,is_core,sort_order,updated_at) VALUES (3,'Publications & Story','Make Glenride legible to the world.','Develop the essays, screenplays, newsletters, campaigns, and long-form work that carry the institute’s ideas.','Writing time, editing, design, layout, publishing, and distribution.','Cornerstone essay, The Borrowed Spell, STARBORN, and the 12-piece campaign.','A publishing house with a recognizable body of work and repeatable rights and licensing pathways.','Published work with the founder’s name on it, selling or licensed.','','gold',1,3,'2026-10-08T17:36:47.000Z');
INSERT OR REPLACE INTO sysmap_departments (id,title,tagline,mandate,cost_center,current_state,future_state,done_looks_like,notes,accent,is_core,sort_order,updated_at) VALUES (4,'Commerce','The cash register.','Bring products, publications, and licensed systems to regular people and institutional customers.','Cost of goods, fulfillment, shipping, payment processing, samples, and quality control.','Reynard’s, the WAVY Ship’s Store, and the Glenride app store.','A clear storefront and licensing operation with dependable fulfillment and customer support.','Revenue that reliably funds the rest of the institute.','','ember',1,4,'2026-10-08T17:36:47.000Z');
INSERT OR REPLACE INTO sysmap_departments (id,title,tagline,mandate,cost_center,current_state,future_state,done_looks_like,notes,accent,is_core,sort_order,updated_at) VALUES (5,'Treasury','The institute’s financial backbone.','Steward reserves, fee streams, token vesting schedules, and department budgets with exact process.','Transaction costs, audits, accounting, and counsel for classification and compliance.','The Safe, frozen tokenomics, and the fairness audit.','An endowment-style treasury that funds cost centers without sacrificing the institute’s independence.','Every movement logged and every allocation matching the published rules.','','gold',1,5,'2026-10-08T17:36:47.000Z');
INSERT OR REPLACE INTO sysmap_departments (id,title,tagline,mandate,cost_center,current_state,future_state,done_looks_like,notes,accent,is_core,sort_order,updated_at) VALUES (6,'Community & Channels','The people, gathered.','Convene the audience, council, channels, and public programs that every future build can draw on.','Moderation tooling, event costs, community programs, and channel operations.','Vapor Wire channels and the Glenride Council concept.','A durable network of participants, supporters, experts, and collaborators around the institute’s work.','Active rooms, a council that meets, and members who bring others.','','teal',1,6,'2026-10-08T17:36:47.000Z');
INSERT OR REPLACE INTO sysmap_departments (id,title,tagline,mandate,cost_center,current_state,future_state,done_looks_like,notes,accent,is_core,sort_order,updated_at) VALUES (7,'Operations','The structure that holds the structure.','Run finance, books, legal, compliance, people operations, filings, and organizational cadence.','Registered agent, accounting, counsel, insurance, filings, and administrative systems.','The business-structure system map and this operating concept.','A professional operating spine that lets departments move without the founder carrying every routine task.','Clean books, current filings, owned processes, and no surprises.','','sage',1,7,'2026-10-08T17:36:47.000Z');
INSERT OR REPLACE INTO sysmap_budget_stages (id,title,description,timing,decision_rule,sort_order,updated_at) VALUES (1,'Plan','Departments propose the next year’s trials and research studies, including data licenses, compute, and staffing.','Year prior','A proposal names the work, expected outcome, resources, readiness, and cost before funds are allocated.',1,'2026-10-08T17:40:19.000Z');
INSERT OR REPLACE INTO sysmap_budget_stages (id,title,description,timing,decision_rule,sort_order,updated_at) VALUES (2,'Raise & deploy','The President raises the annual budget and deploys it to the Lead Director.','Start of budget year','Funds enter the operating chain through the President and move to the Lead Director for allocation.',2,'2026-10-08T17:40:19.000Z');
INSERT OR REPLACE INTO sysmap_budget_stages (id,title,description,timing,decision_rule,sort_order,updated_at) VALUES (3,'Allocate','The Lead Director divides the budget across departments, equally or by agreed criteria.','Annual allocation','Criteria can include strategic priority, prior-year results, and readiness to execute.',3,'2026-10-08T17:40:19.000Z');
INSERT OR REPLACE INTO sysmap_budget_stages (id,title,description,timing,decision_rule,sort_order,updated_at) VALUES (4,'Execute','Department Directors and Managers run the approved studies; spending is tracked as each study completes.','During the year','Each completed study closes against its approved plan, actual spend, and result.',4,'2026-10-08T17:40:19.000Z');
INSERT OR REPLACE INTO sysmap_budget_stages (id,title,description,timing,decision_rule,sort_order,updated_at) VALUES (5,'Reallocate','Leftover budget is reassigned to another approved project so every dollar stays in motion.','As work closes','Unspent funds return to the allocation pool rather than sitting inside a finished study.',5,'2026-10-08T17:40:19.000Z');
INSERT OR REPLACE INTO sysmap_hierarchy (id,title,holder,responsibility,sort_order,updated_at) VALUES (1,'Founder & Interim President','D’Vaughn House','Sets the institutional direction, raises the annual budget, and deploys it to the Lead Director.',1,'2026-10-08T17:40:19.000Z');
INSERT OR REPLACE INTO sysmap_hierarchy (id,title,holder,responsibility,sort_order,updated_at) VALUES (2,'Lead Director','','Turns presidential direction into an operating year, allocates the budget across departments, and holds directors to the plan.',2,'2026-10-08T17:40:19.000Z');
INSERT OR REPLACE INTO sysmap_hierarchy (id,title,holder,responsibility,sort_order,updated_at) VALUES (3,'Department Directors','One per department','Own department mandates, cost centers, study portfolios, results, and reporting.',3,'2026-10-08T17:40:19.000Z');
INSERT OR REPLACE INTO sysmap_hierarchy (id,title,holder,responsibility,sort_order,updated_at) VALUES (4,'Managers','Under each Department Director','Coordinate trials, research studies, data licenses, staffing, schedules, and spend at the working level.',4,'2026-10-08T17:40:19.000Z');
INSERT OR REPLACE INTO sysmap_hierarchy (id,title,holder,responsibility,sort_order,updated_at) VALUES (5,'Teams','','Carry out the research, product, publishing, commerce, treasury, community, and operations work.',5,'2026-10-08T17:40:19.000Z');
INSERT OR REPLACE INTO sysmap_organization (id,premise,current_title,current_body,future_title,future_body,updated_at) VALUES (1,'An independent research institute with a venture studio inside. Research earns the credibility; products fund the research.','Founder & Interim President','D’Vaughn House leads Glenride at the top of the operating chain, raises and deploys the annual budget, sets direction, and holds the institutional standard.','President → Lead Director → Department Directors → Managers → Teams','Authority and budgets move through an explicit chain so each department can run planned work without every decision returning to the founder.','2026-10-08T17:40:19.000Z');
